style.css:
@-moz-document domain("youtube.com") {
/* ————— BACKGROUND OVERLAY (STABLE) ————— */
body::after {
  content: "";
  position: fixed;
  inset: 0;

  background: url("https://i.pinimg.com/originals/76/0e/72/760e725f5ff8812ed6748f07f4957f34.png")
              no-repeat center center;
  background-size: cover;

  z-index: 3;
  opacity: 100;
  pointer-events: none;
}

/* ————— KEEP CONTENT ABOVE OVERLAY ————— */
ytd-app,
ytd-page-manager,
#content,
#container,
#primary,
#secondary,
#masthead-container,
#guide,
#comments {
  position: relative;
  z-index: 1;
}

/* ————— SOFTEN BLACK PANELS ————— */
#masthead-container,
#guide,
#secondary,
#comments {
  background-color: rgba(0, 0, 0, 0.55) !important;
  backdrop-filter: blur(3px);
}

/* ————— VIDEO GRID ————— */
ytd-rich-grid-renderer,
ytd-grid-renderer {
  background-color: rgba/*[[#4FC3F7]]*/ !important;
}

/* ————— TEXT READABILITY ————— */
yt-formatted-string,
#text,
a {
  color: #ffffff !important;
  text-shadow: 0 0 4px rgba(0,0,0,0.9);
}

/* ————— SCROLLBAR ————— */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.4);
  border-radius: 4px;
}
}
